mapper.delete:
DELETE FROM tb_saved_notification
WHERE account_id = #{accountId}
  AND event_id = #{eventId}

mapper.select:
SELECT event_id, account_id
FROM tb_saved_notification
WHERE event_id = #{eventId}
AND account_id = #{accountId}

SELECT event_id, account_id, title, ticket_open_at
FROM tb_saved_notification
WHERE ticket_open_at BETWEEN #{start} AND #{end}
